/// Supplied decoded text observations, independent of image bytes, inspection,
/// normalization, title fallback, stored metadata or committed custody.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct MetadataText {
    pub title: String,
    pub description: String,
}

impl MetadataText {
    pub(super) fn from_fields(title: &str, description: &str) -> Self {
        Self {
            title: trim_space(title).to_owned(),
            description: trim_space(description).to_owned(),
        }
    }
}

fn is_space(ch: char) -> bool {
    // Exact Go Unicode15 IsSpace Latin1 switch plus _White_Space R16.
    // Its R32 is empty; JSON lexical whitespace remains a separate rule.
    matches!(ch,
        '\u{0009}'..='\u{000d}' | '\u{0020}' | '\u{0085}' | '\u{00a0}' |
        '\u{1680}' | '\u{2000}'..='\u{200a}' | '\u{2028}' | '\u{2029}' |
        '\u{202f}' | '\u{205f}' | '\u{3000}'
    )
}

fn trim_space(value: &str) -> &str {
    // Go unquote has already replaced invalid UTF8/surrogates. Valid-string
    // character boundaries therefore preserve TrimSpace's byte boundaries.
    let Some((start, _)) = value.char_indices().find(|(_, ch)| !is_space(*ch)) else {
        return "";
    };
    let end = value
        .char_indices()
        .rev()
        .find(|(_, ch)| !is_space(*ch))
        .map_or(start, |(index, ch)| index + ch.len_utf8());
    &value[start..end]
}
